window.counterUp={default:function(e,t={}){const n=t.duration||1e3,r=t.delay||16,a=parseFloat(e.innerHTML.replace(/,/g,""));if(isNaN(a))return;const o=n/r;let l=0;e.style.visibility="visible";const i=setInterval((()=>{l++;const t=l/o,n=Math.floor(a*t);e.innerHTML=n.toLocaleString(),l>=o&&(clearInterval(i),e.innerHTML=a.toLocaleString())}),r)}};
